#!/usr/bin/env python3
"""Verify that the optimizations are correctly applied to kernels.py."""

import re

def check_optimizations():
    """Check that the key optimizations are present in the code."""

    file_path = "/home/ubuntu/OmniPerf-Bench/perf-agents-bench/.work/worktrees/sglang_core/sglang_core-0000/python/sglang/srt/layers/moe/ep_moe/kernels.py"

    with open(file_path, 'r') as f:
        content = f.read()

    checks = {
        "pre_reorder_triton_kernel": {
            "pattern": r"def pre_reorder_triton_kernel\(.*?\):(.*?)(?=\n@triton\.jit|\ndef |\Z)",
            "optimizations": [
                r"# Pre-load input data once",  # Comment indicating optimization
                r"in_data = tl\.load\(src_ptr \+ offset, mask=mask\)",  # Load once per block
                r"for idx in range\(topk\):",  # Process experts per block
            ],
            "status": False
        },
        "post_reorder_triton_kernel": {
            "pattern": r"def post_reorder_triton_kernel\(.*?\):(.*?)(?=\n@triton\.jit|\ndef |\Z)",
            "optimizations": [
                r"# Pre-load expert info",  # Comment indicating optimization
                r"expert_ids = tl\.zeros\(\[topk\], dtype=tl\.int32\)",  # Pre-allocate arrays
                r"valid_experts = tl\.zeros\(\[topk\], dtype=tl\.int1\)",  # Validity flags
                r"for idx in range\(topk\):",  # Pre-load loop
            ],
            "status": False
        },
        "deepep_permute_triton_kernel": {
            "pattern": r"def deepep_permute_triton_kernel\(.*?\):(.*?)(?=\n@triton\.jit|\ndef |\Z)",
            "optimizations": [
                r"# Pre-load dst indices",  # Comment indicating optimization
                r"dst_idxs = tl\.zeros\(\[topk\], dtype=tl\.int32\)",  # Pre-allocate
                r"valid_dsts = tl\.zeros\(\[topk\], dtype=tl\.int1\)",  # Validity flags
            ],
            "status": False
        },
        "deepep_post_reorder_triton_kernel": {
            "pattern": r"def deepep_post_reorder_triton_kernel\(.*?\):(.*?)(?=\n@triton\.jit|\ndef |\Z)",
            "optimizations": [
                r"# Pre-load expert info",  # Comment indicating optimization
                r"dst_idxs = tl\.zeros\(\[topk\], dtype=tl\.int32\)",  # Pre-allocate
                r"valid_dsts = tl\.zeros\(\[topk\], dtype=tl\.int1\)",  # Validity flags
            ],
            "status": False
        }
    }

    all_passed = True

    for kernel_name, check_info in checks.items():
        print(f"\nChecking {kernel_name}...")

        # Extract kernel code
        match = re.search(check_info["pattern"], content, re.DOTALL)
        if not match:
            print(f"  ❌ Kernel not found!")
            all_passed = False
            continue

        kernel_code = match.group(1)

        # Check for each optimization
        kernel_passed = True
        for opt_pattern in check_info["optimizations"]:
            if re.search(opt_pattern, kernel_code):
                print(f"  ✅ Found: {opt_pattern[:50]}...")
            else:
                print(f"  ❌ Missing: {opt_pattern[:50]}...")
                kernel_passed = False
                all_passed = False

        if kernel_passed:
            print(f"  ✅ {kernel_name} optimizations verified!")
            check_info["status"] = True

    print("\n" + "="*60)
    if all_passed:
        print("✅ All optimizations successfully applied!")
        return 0
    else:
        print("❌ Some optimizations are missing!")
        return 1

if __name__ == "__main__":
    import sys
    sys.exit(check_optimizations())

