#!/usr/bin/env python3
"""Verify that the optimizations have been correctly applied."""

import sys

def verify_optimizations():
    """Verify all optimizations are present in the kernels.py file."""

    file_path = "/home/ubuntu/OmniPerf-Bench/perf-agents-bench/.work/worktrees/sglang_core/sglang_core-0000/python/sglang/srt/layers/moe/ep_moe/kernels.py"

    print("="*70)
    print("Verifying MoE Align Block Size Optimizations")
    print("="*70)

    try:
        with open(file_path, 'r') as f:
            content = f.read()

        # Test 1: Check file compiles
        print("\n[Test 1] Checking Python syntax...")
        try:
            compile(content, file_path, 'exec')
            print("✅ PASS: File compiles successfully")
        except SyntaxError as e:
            print(f"❌ FAIL: Syntax error at line {e.lineno}: {e.msg}")
            return False

        # Test 2: Check for pre_reorder_triton_kernel optimization
        print("\n[Test 2] Checking pre_reorder_triton_kernel...")
        if "# Pre-load input data once to avoid redundant memory accesses" in content:
            print("✅ PASS: Found pre-loading optimization comment")
        else:
            print("❌ FAIL: Missing pre-loading optimization comment")
            return False

        # Check that input is loaded once per block
        lines = content.split('\n')
        in_pre_reorder = False
        found_pre_load = False
        found_process_experts = False

        for i, line in enumerate(lines):
            if 'def pre_reorder_triton_kernel' in line:
                in_pre_reorder = True
            elif in_pre_reorder and 'def ' in line and 'pre_reorder' not in line:
                in_pre_reorder = False

            if in_pre_reorder:
                if 'in_data = tl.load(src_ptr + offset, mask=mask)' in line:
                    found_pre_load = True
                if '# Process each expert for this block' in line:
                    found_process_experts = True

        if found_pre_load and found_process_experts:
            print("✅ PASS: Input data is pre-loaded once per block")
        else:
            print("❌ FAIL: Input data loading pattern not optimized")
            return False

        # Test 3: Check for post_reorder_triton_kernel optimization
        print("\n[Test 3] Checking post_reorder_triton_kernel...")
        if "# Pre-load expert info to avoid redundant memory accesses" in content:
            print("✅ PASS: Found pre-loading optimization comment")
        else:
            print("❌ FAIL: Missing pre-loading optimization comment")
            return False

        # Check for pre-allocated arrays
        if "expert_ids = tl.zeros([topk], dtype=tl.int32)" in content:
            print("✅ PASS: Found pre-allocated expert_ids array")
        else:
            print("❌ FAIL: Missing pre-allocated expert_ids array")
            return False

        if "valid_experts = tl.zeros([topk], dtype=tl.int1)" in content:
            print("✅ PASS: Found pre-allocated valid_experts array")
        else:
            print("❌ FAIL: Missing pre-allocated valid_experts array")
            return False

        # Test 4: Check for deepep_permute_triton_kernel optimization
        print("\n[Test 4] Checking deepep_permute_triton_kernel...")
        if "# Pre-load dst indices to avoid redundant memory accesses" in content:
            print("✅ PASS: Found pre-loading optimization comment")
        else:
            print("❌ FAIL: Missing pre-loading optimization comment")
            return False

        if "dst_idxs = tl.zeros([topk], dtype=tl.int32)" in content:
            print("✅ PASS: Found pre-allocated dst_idxs array")
        else:
            print("❌ FAIL: Missing pre-allocated dst_idxs array")
            return False

        # Test 5: Check for deepep_post_reorder_triton_kernel optimization
        print("\n[Test 5] Checking deepep_post_reorder_triton_kernel...")
        # This should also have the pre-loading comment
        found_count = content.count("# Pre-load expert info to avoid redundant memory accesses")
        if found_count >= 2:
            print("✅ PASS: Found pre-loading optimization in deepep_post_reorder")
        else:
            print("❌ FAIL: Missing pre-loading optimization in deepep_post_reorder")
            return False

        # Test 6: Verify no regression in original logic
        print("\n[Test 6] Checking for regression in original logic...")
        # Check that key operations are still present
        if "tl.load(src_ptr + offset, mask=mask)" in content:
            print("✅ PASS: Data loading operations preserved")
        else:
            print("❌ FAIL: Data loading operations missing")
            return False

        if "tl.store(" in content:
            print("✅ PASS: Data storing operations preserved")
        else:
            print("❌ FAIL: Data storing operations missing")
            return False

        print("\n" + "="*70)
        print("✅ ALL TESTS PASSED - Optimizations verified successfully!")
        print("="*70)
        return True

    except FileNotFoundError:
        print(f"❌ FAIL: File not found: {file_path}")
        return False
    except Exception as e:
        print(f"❌ FAIL: Unexpected error: {e}")
        return False

if __name__ == "__main__":
    success = verify_optimizations()
    sys.exit(0 if success else 1)

